import java.util.LinkedList;
import java.util.ListIterator;

public class HistorialNavegador {
    public static void main(String[] args) {
        LinkedList<String> historial = new LinkedList<>();
        historial.add("google.com");
        historial.add("github.com");
        historial.add("stackoverflow.com");

        ListIterator<String> iterador = historial.listIterator();
        while (iterador.hasNext()) iterador.next();

        // Go back 1
        String actual = iterador.previous();
        System.out.println("Back to: " + actual);

        // Go back 1 more
        actual = iterador.previous();
        System.out.println("Back to: " + actual);

        // Go forward 1
        actual = iterador.next();
        System.out.println("Forward to: " + actual);

        // Go forward 1 more
        actual = iterador.next();
        System.out.println("Forward to: " + actual);
    }
}
